from pathlib import Path
import tarfile

from kaggle_environments import make

AGENT_SOURCE = '"""Kaggriculture baseline 2: diversified wheat/melon market hedge."""\n\nCROPS = {\n    "WHEAT": {"first": 2, "max_day": 4, "yield": 6, "seed": 10, "last_plant": 24},\n    "CARROT": {"first": 2, "max_day": 3, "yield": 4, "seed": 20, "last_plant": 25},\n    "TOMATO": {"first": 8, "max_day": 8, "yield": 4, "seed": 50, "last_plant": 19},\n    "STRAWBERRY": {"first": 10, "max_day": 10, "yield": 4, "seed": 100, "last_plant": 17},\n    "MELON": {"first": 10, "max_day": 12, "yield": 6, "seed": 80, "last_plant": 16},\n}\n\nPRODUCTS = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL")\nTARGET_TILES = 25\nHANDS_PER_DAY = 8\n\n\ndef _move_toward(position, target, step, unit_index):\n    x, y = position\n    tx, ty = target\n    vertical_first = (step + unit_index) % 2 == 0\n    if vertical_first and y != ty:\n        return ["SOUTH" if ty > y else "NORTH"]\n    if x != tx:\n        return ["EAST" if tx > x else "WEST"]\n    if y != ty:\n        return ["SOUTH" if ty > y else "NORTH"]\n    return ["PASS"]\n\n\ndef _field_cells(farm):\n    cells = []\n    for y, row in enumerate(farm["tiles"]):\n        xs = range(len(row) - 1, -1, -1) if y % 2 == 0 else range(len(row))\n        for x in xs:\n            if row[x] != "LOCKED":\n                cells.append((x, y))\n    return cells[:TARGET_TILES]\n\n\ndef _crop_plan(obs, farm):\n    prices = obs.get("market", {}).get("prices", {})\n    opponent = obs.get("farms", [farm, farm])[1 - int(obs.get("player", 0))]\n    opponent_melons = 0\n    for row in opponent.get("tiles", []):\n        for tile in row:\n            if isinstance(tile, dict) and tile.get("kind") == "PLANT" and tile.get("crop") == "MELON":\n                opponent_melons += 1\n\n    # Premium melons are excellent while uncontested, but their quadratic glut\n    # penalty is severe. Fall back to stable wheat if the rival crowds the trade.\n    melon_slots = 10\n    if int(prices.get("MELON", 250)) < 140 or opponent_melons >= 8:\n        melon_slots = 4\n    carrot_slots = 5 if "PET_CAFE" in obs.get("town", {}).get("unlocked_shops", []) else 2\n    wheat_slots = TARGET_TILES - melon_slots - carrot_slots\n\n    plan = []\n    for crop, count in (("MELON", melon_slots), ("CARROT", carrot_slots), ("WHEAT", wheat_slots)):\n        plan.extend([crop] * count)\n    return {cell: plan[i] for i, cell in enumerate(_field_cells(farm))}\n\n\ndef _build_tasks(obs, farm, private, plan):\n    day = int(obs.get("day", 0))\n    seeds_left = {crop: int(private.get("seeds", {}).get(crop, 0)) for crop in CROPS}\n    tasks = []\n    for (x, y), desired_crop in plan.items():\n        tile = farm["tiles"][y][x]\n        if tile is None:\n            if day <= CROPS[desired_crop]["last_plant"] and seeds_left[desired_crop] > 0:\n                tasks.append((3, (x, y), ["PLANT", desired_crop]))\n                seeds_left[desired_crop] -= 1\n            continue\n        if not isinstance(tile, dict):\n            continue\n        if tile.get("kind") == "WEED":\n            tasks.append((2, (x, y), ["DIG"]))\n            continue\n        if tile.get("kind") != "PLANT":\n            continue\n        crop = tile.get("crop")\n        info = CROPS.get(crop, CROPS[desired_crop])\n        age = day - int(tile.get("planted_day", day))\n        available = int(tile.get("yield_units", 0))\n        should_harvest = age >= info["max_day"]\n        if day >= 28 and age >= info["first"] and available > 0:\n            should_harvest = True\n        if should_harvest and available > 0:\n            tasks.append((0, (x, y), ["HARVEST"]))\n        elif not tile.get("watered_today", False):\n            tasks.append((1, (x, y), ["WATER"]))\n    return tasks\n\n\ndef _assign_tasks(obs, farm, private, plan):\n    step = int(obs.get("step", 0))\n    positions = [farm["farmer"]] + list(farm.get("hands", []))\n    inventories = list(private.get("inventories", []))\n    actions = [["PASS"] for _ in positions]\n    available_units = []\n    for idx, position in enumerate(positions):\n        inventory = inventories[idx] if idx < len(inventories) else {}\n        if sum(int(v) for v in inventory.values()) > 0:\n            if tuple(position) == (4, 4):\n                actions[idx] = ["DROP"]\n            else:\n                actions[idx] = _move_toward(position, (4, 4), step, idx)\n        else:\n            available_units.append(idx)\n\n    tasks = _build_tasks(obs, farm, private, plan)\n    for priority in (0, 1, 2, 3):\n        pending = [task for task in tasks if task[0] == priority]\n        while pending and available_units:\n            best = None\n            for task_index, task in enumerate(pending):\n                tx, ty = task[1]\n                for unit_index in available_units:\n                    ux, uy = positions[unit_index]\n                    candidate = (abs(ux - tx) + abs(uy - ty), task_index, unit_index)\n                    if best is None or candidate < best:\n                        best = candidate\n            _, task_index, unit_index = best\n            _, target, operation = pending.pop(task_index)\n            available_units.remove(unit_index)\n            actions[unit_index] = operation if tuple(positions[unit_index]) == target else _move_toward(\n                positions[unit_index], target, step, unit_index\n            )\n    return actions\n\n\ndef _market_orders(obs, farm, private, plan):\n    day = int(obs.get("day", 0))\n    hour = int(obs.get("hour", 0))\n    shed = private.get("shed", {})\n    seeds = private.get("seeds", {})\n    orders = []\n    for product in PRODUCTS:\n        amount = int(shed.get(product, 0))\n        if amount > 0:\n            orders.append(["SELL", product, amount])\n    if hour == 0:\n        orders.extend([["HIRE"] for _ in range(HANDS_PER_DAY)])\n\n    desired = {crop: 0 for crop in CROPS}\n    planted = {crop: 0 for crop in CROPS}\n    for (x, y), crop in plan.items():\n        desired[crop] += 1\n        tile = farm["tiles"][y][x]\n        if isinstance(tile, dict) and tile.get("kind") == "PLANT":\n            planted[tile.get("crop")] = planted.get(tile.get("crop"), 0) + 1\n    cash = int(farm["money"])\n    for crop in ("MELON", "WHEAT", "CARROT"):\n        if day > CROPS[crop]["last_plant"]:\n            continue\n        need = max(0, desired[crop] - planted.get(crop, 0) - int(seeds.get(crop, 0)))\n        affordable = cash // CROPS[crop]["seed"]\n        buy = min(need, affordable)\n        if buy > 0:\n            orders.append(["BUY_SEED", crop, buy])\n            cash -= buy * CROPS[crop]["seed"]\n    return orders[:10]\n\n\ndef agent(obs):\n    player = int(obs.get("player", 0))\n    farms = obs.get("farms", [])\n    if not farms or player >= len(farms):\n        return {"farmer": ["PASS"], "hands": [], "market": []}\n    farm = farms[player]\n    private = obs.get("private", {}) or {}\n    plan = _crop_plan(obs, farm)\n    actions = _assign_tasks(obs, farm, private, plan)\n    return {\n        "farmer": actions[0] if actions else ["PASS"],\n        "hands": actions[1:],\n        "market": _market_orders(obs, farm, private, plan),\n    }\n'
working = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
main_path = working / "main.py"
archive_path = working / "submission.tar.gz"
main_path.write_text(AGENT_SOURCE, encoding="utf-8")

namespace = {}
exec(compile(AGENT_SOURCE, "main.py", "exec"), namespace)
candidate = namespace["agent"]

results = []
for seed in range(3):
    env = make("kaggriculture", configuration={"episodeSteps": 720, "seed": seed}, debug=True)
    final = env.run([candidate, "starter"])[-1]
    row = {
        "seed": seed,
        "status": [state.status for state in final],
        "rewards": [float(state.reward) for state in final],
    }
    assert row["status"] == ["DONE", "DONE"], row
    results.append(row)

with tarfile.open(archive_path, "w:gz") as archive:
    archive.add(main_path, arcname="main.py")

print("Smoke-test results:", results)
print("Created:", archive_path, "bytes=", archive_path.stat().st_size)
